// Tablonun sıralama ve hücre yazımı ABACUS ile (giris-alanlari-standardi.md). Arc metinleri İngilizce sıralayıcıyla
// karşılaştırıyor ve sayıyı, tarihi düz String ile yazıyordu ("1234.5", "Fri Oct 16 2026"). Burada sıra Türkçe alfabedir
// (ABACUS `collate`: ç c'den, ı i'den önce), para kuruş tam sayısından yazılır, sayı ve tarih Türkçe biçimdedir.
// Saf dosya: React yok, test edilir.
import { collate, date as abacusDate, money } from "@snn/abacus-core";

/** Hücre biçimi. Verilmezse değerin türüne bakılır: sayı → "number", Date → "date", diğerleri metin. */
export type CellFormat = "text" | "number" | "money" | "date";
export type CellCurrency = "TRY" | "USD" | "EUR";
export type CellSpec = { format?: CellFormat; currency?: CellCurrency; digits?: number };

const isEmpty = (value: unknown) => value == null || value === "";
const decimalsOf = (value: number) => (String(value).split(".")[1] ?? "").length;
const isoOf = (value: Date) => `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, "0")}-${String(value.getDate()).padStart(2, "0")}`;

/** İki metni Türkçe alfabeye göre karşılaştırır (ABACUS `collate.compare`): "Çorum" "Denizli"den, "Iğdır" "İzmir"den önce gelir. */
export const compareText = (left: string, right: string) => collate.compare(left, right);

/** Sayıyı binlik ayraçlı yazar; `digits` verilmezse değerin kendi ondalığı (en çok 4) korunur. 1234.5 → "1.234,5", -0.5 → "-0,5". */
export function formatNumberCell(value: number, digits?: number) {
  const places = digits ?? Math.min(4, decimalsOf(value));
  const text = money.fmtDecimalGrouped(Math.abs(value), places);
  return value < 0 && text !== "—" ? `-${text}` : text;
}

/** Hücre değerini yazar. Para kuruştur: 123450 → "₺1.234,50". Tarih Date ya da ISO gündür: "16.10.2026". Boş değer "–". */
export function formatCell(value: unknown, spec: CellSpec = {}): string {
  if (isEmpty(value)) return "–";
  const format = spec.format ?? (typeof value === "number" ? "number" : value instanceof Date ? "date" : "text");
  if (format === "money" && typeof value === "number") return money.format(value, { currency: spec.currency ?? "TRY", kurus: true, zero: "symbol" });
  if (format === "number" && typeof value === "number") return formatNumberCell(value, spec.digits);
  if (format === "date") return abacusDate.format(value instanceof Date ? isoOf(value) : String(value), "short");
  return String(value);
}

/** Sayfa sayısı: 48 kayıt, 10'ar → 5. Sayfa boyu yoksa ya da geçersizse 1. */
export const pageCountOf = (total: number, pageSize?: number) => (pageSize && pageSize > 0 ? Math.max(1, Math.ceil(total / pageSize)) : 1);

/** Sayfanın kapsadığı kayıtlar: "11–20". Sayılar ABACUS ile gruplanır ("1.001–1.010"). */
export function pageSpan(page: number, pageSize: number, total: number) {
  const start = total ? (page - 1) * pageSize + 1 : 0;
  const end = Math.min(total, page * pageSize);
  return `${money.fmtDecimalGrouped(start)}–${money.fmtDecimalGrouped(end)}`;
}

/** Sayfa satırı: "11–20 / 48 kayıt". Seçim satırı toplamı zaten söylüyorsa yalnız `pageSpan` yazılır. */
export const rangeLabel = (page: number, pageSize: number, total: number, noun: string) => `${pageSpan(page, pageSize, total)} / ${money.fmtDecimalGrouped(total)} ${noun}`;

/** Sıralama duyurusu: "Tutar sütununa göre azalan sıralandı". */
export const sortAnnouncement = (label: string, direction: "asc" | "desc") => `${label} sütununa göre ${direction === "asc" ? "artan" : "azalan"} sıralandı`;

/* Hücreler opaktır; sıralama sırasında birbirini geçen satırlar metni karıştırmadan birbirini temizce örter. */
.wrapper { --column-tint: var(--surface-muted); position: relative; width: 100%; min-width: 0; max-width: 100%; overflow: hidden; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); color: var(--foreground); font-family: var(--font-body); }
.scroller { position: relative; overflow-x: auto; overscroll-behavior-x: contain; }
.band { position: absolute; top: 0; bottom: 0; background: var(--column-tint); pointer-events: none; }
.table { position: relative; z-index: 1; width: 100%; min-width: 560px; border-collapse: separate; border-spacing: 0; font-size: var(--text-sm); line-height: var(--leading-body); letter-spacing: var(--tracking-body); text-align: left; }
.table[data-fixed] { table-layout: fixed; }
.table caption, .srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.selectCol { width: 44px; }

.table th, .table td { --cell-base: var(--surface); --cell-fill: var(--cell-base); background-color: var(--cell-fill); transition: background-color var(--duration-standard) var(--ease-standard), color var(--duration-standard) var(--ease-standard); }
.table th[data-sorted], .table td[data-sorted] { --cell-base: var(--column-tint); }
.table th { height: 44px; padding: 0 var(--space-4); border-bottom: 1px solid var(--border); color: var(--text-muted); font-size: var(--text-sm); font-weight: 500; text-align: left; white-space: nowrap; }
.table th[data-sortable] { padding: 0; }
.table th[data-sorted] { color: var(--foreground); }
.table td { height: 52px; padding: 0 var(--space-4); border-bottom: 1px solid var(--border-subtle); color: var(--foreground); font-weight: 400; vertical-align: middle; overflow-wrap: anywhere; }
.table tbody tr:last-child td { border-bottom: 0; }
.table [data-numeric] { text-align: right; font-variant-numeric: tabular-nums; }
.table[data-selectable] tbody tr { cursor: pointer; -webkit-tap-highlight-color: transparent; }
.table[data-selectable] tbody tr[data-selected] td { --cell-fill: color-mix(in oklab, var(--accent) 8%, var(--cell-base)); }
.table[data-selectable] [data-primary]:not([data-sortable]), .table[data-selectable] th[data-primary] .sortButton { padding-left: var(--space-2); }

.sortButton { display: flex; width: 100%; height: 44px; align-items: center; justify-content: flex-start; border: 0; padding: 0 var(--space-4); background: transparent; color: inherit; font: inherit; letter-spacing: inherit; cursor: pointer; -webkit-tap-highlight-color: transparent; }
.table th[data-numeric] .sortButton { justify-content: flex-end; }
.sortInner { display: inline-flex; align-items: center; gap: 6px; border-radius: var(--radius-control); transition: color var(--duration-fast) var(--ease-standard); }
/* Sağa yaslı sütunlarda ok öndedir; başlık altındaki rakamlarla hizalanır. */
.table th[data-numeric] .sortInner { flex-direction: row-reverse; }
.sortIcon { position: relative; display: grid; width: 16px; height: 16px; flex: none; place-items: center; }
.sortHint, .sortArrow { position: absolute; inset: 0; display: grid; place-items: center; }
.sortHint { color: var(--text-muted); opacity: 0; transition: opacity var(--duration-fast) var(--ease-standard); }
.sortArrow { color: var(--foreground); }
.sortButton:focus-visible .sortHint { opacity: .6; }
.table th[data-sorted] .sortHint { opacity: 0; }

.selectCell { width: 44px; }
.table .selectCell { padding: 0 0 0 var(--space-4); }
.selectHit { position: relative; display: flex; width: 100%; height: 44px; align-items: center; cursor: pointer; }
.selectInput { position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; opacity: 0; cursor: pointer; }
.selectBox { position: relative; display: block; width: 18px; height: 18px; flex: none; border: 1px solid var(--border-strong); border-radius: 5px; background: var(--surface); color: var(--control-glyph); pointer-events: none; transition: border-color var(--duration-fast) var(--ease-standard), transform var(--duration-spring) var(--ease-spring); }
.selectBox[data-on] { border-color: var(--control-on); }
.selectFill { position: absolute; inset: -1px; border-radius: inherit; background: var(--control-on); }
.selectMark { position: absolute; inset: -1px; width: 18px; height: 18px; overflow: visible; }
/* Yerel onay kutusu gizlidir; klavye odak çizgisi görünen kutuya çizilir. */
.selectInput:focus-visible + .selectBox { outline: var(--focus-outline-width, 2px) solid var(--focus-outline, color-mix(in oklab, var(--accent-strong) 72%, transparent)); outline-offset: 2px; }
.selectInput:active + .selectBox { transform: scale(.95); transition: border-color var(--duration-fast) var(--ease-standard), transform 110ms var(--ease-standard); }

.footer { display: flex; height: 44px; align-items: center; justify-content: space-between; gap: var(--space-3); padding: 0 var(--space-2) 0 var(--space-4); border-top: 1px solid var(--border); color: var(--text-muted); font-size: var(--text-sm); line-height: var(--leading-body); letter-spacing: var(--tracking-body); }
.count { display: inline-flex; min-width: 0; align-items: baseline; gap: .28em; white-space: nowrap; transition: color var(--duration-standard) var(--ease-standard); }
.count[data-active] { color: var(--foreground); }
.swap { display: inline-block; }
.swapInner { position: relative; display: inline-flex; width: max-content; }
.swapText { display: inline-block; white-space: nowrap; }
.number { font-variant-numeric: tabular-nums; }
/* Sayfalı tabloda seçim ve sayfalama aynı satırı paylaşır; dar alanda sayfalama alta iner. */
.footer[data-paged] { height: auto; min-height: 52px; flex-wrap: wrap; padding-block: var(--space-2); }
.selection { display: inline-flex; min-width: 0; align-items: center; gap: var(--space-3); }
.clear { height: 30px; flex: none; border: 0; border-radius: var(--radius-control); padding: 0 var(--space-3); background: transparent; color: var(--foreground); font: inherit; font-weight: 500; letter-spacing: inherit; cursor: pointer; transition: background-color var(--duration-fast) var(--ease-standard); -webkit-tap-highlight-color: transparent; }
/* Sayfalama (SNN ekledi): "11–20 / 48 kayıt" ve katalogdaki sayfalama, satırın sağında. */
.pager { display: inline-flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: var(--space-2) var(--space-3); margin-left: auto; }
.range { font-variant-numeric: tabular-nums; white-space: nowrap; }

.empty { height: 120px !important; color: var(--text-muted) !important; text-align: center !important; }

@media (hover: hover) and (pointer: fine) {
  .table tbody tr:hover td { --cell-fill: color-mix(in oklab, var(--foreground) 3%, var(--cell-base)); }
  .table[data-selectable] tbody tr[data-selected]:hover td { --cell-fill: color-mix(in oklab, var(--accent) 11%, var(--cell-base)); }
  .table tbody tr:has(.empty):hover td { --cell-fill: var(--cell-base); }
  .sortButton:hover .sortInner { color: var(--foreground); }
  .sortButton:hover .sortHint { opacity: .6; }
  .table th[data-sorted] .sortButton:hover .sortHint { opacity: 0; }
  .selectHit:hover .selectBox:not([data-on]) { border-color: var(--text-muted); }
  .clear:hover { background: var(--surface-muted); }
}

@media (max-width: 620px) {
  .scroller { overflow: visible; }
  .band { display: none; }
  .table { display: block; width: 100%; min-width: 0; max-width: 100%; }
  .table thead { display: block; }
  /* Başlık bir sıralama düğmeleri şeridine dönüşür; telefonda sıralama tek dokunuş uzakta kalır. */
  .table thead tr { display: flex; align-items: center; gap: var(--space-1); padding: var(--space-1) var(--space-2); overflow-x: auto; border-bottom: 1px solid var(--border); scrollbar-width: none; }
  .table thead tr::-webkit-scrollbar { display: none; }
  .table th { display: block; flex: none; height: auto; border: 0; padding: 0; background: transparent; }
  /* "Hepsini seç" iğneli kalır, sıralama düğmeleri altından kayar. */
  .table th.selectCell { position: sticky; left: calc(-1 * var(--space-2)); z-index: 1; width: 40px; margin-left: calc(-1 * var(--space-2)); padding: 0 0 0 var(--space-3); background: var(--surface); }
  .table th.selectCell .selectHit { height: 32px; }
  /* Şerit kaydıkça iğneli hücreden çıkan solma, altından kayan sözcüğü gizler. */
  .table th.selectCell::after { position: absolute; top: 0; bottom: 0; left: 100%; width: 36px; background: linear-gradient(to right, var(--surface) 45%, transparent); content: ""; opacity: 0; pointer-events: none; }
  /* Kaydırmaya bağlı canlandırma olmayan tarayıcılar solmayı bir kez, sıfır sürede oynatıp açık bırakırdı; onlarda kapalı kalır. */
  @supports (animation-timeline: scroll()) { .table th.selectCell::after { animation: stripFade linear both; animation-timeline: scroll(nearest inline); animation-range: 0 24px; } }
  .table th .sortButton, .table[data-selectable] th[data-primary] .sortButton { width: auto; height: 32px; border-radius: var(--radius-control); padding: 0 10px; transition: background-color var(--duration-standard) var(--ease-standard), color var(--duration-standard) var(--ease-standard); }
  .table th[data-sorted] .sortButton { background: var(--surface-muted); }
  .table th[data-numeric] .sortInner { flex-direction: row; }
  .sortButton:focus-visible { --focus-outline-offset: 1px; }
  /* Kart görünümü (SNN ekledi; Arc satırı iki satıra katlıyordu). Her kayıt bir karttır: üstte ilk sütun ve ilk sayı sütunu,
     altında kalan sütunlar etiket–değer satırları olarak. Etiket `data-label`dan gelir; ekran okuyucu tablo yapısını okumaya devam eder. */
  .table tbody { display: grid; width: 100%; gap: var(--space-2); padding: var(--space-2); box-sizing: border-box; background: var(--surface-muted); }
  .table tbody tr { --row-fill: var(--surface); position: relative; display: grid; width: 100%; box-sizing: border-box; grid-template-columns: minmax(0, 1fr) auto; align-items: baseline; gap: 6px var(--space-3); padding: 12px var(--space-4); border: 1px solid var(--border-subtle); border-radius: var(--radius-control); background-color: var(--row-fill); transition: background-color var(--duration-standard) var(--ease-standard), border-color var(--duration-standard) var(--ease-standard); }
  .table[data-selectable] tbody tr { padding-left: 44px; }
  .table[data-selectable] tbody tr[data-selected] { --row-fill: color-mix(in oklab, var(--accent) 8%, var(--surface)); border-color: color-mix(in oklab, var(--accent) 30%, var(--border-subtle)); }
  .table td { grid-column: 1 / -1; display: flex; min-width: 0; height: auto; justify-content: space-between; gap: var(--space-3); border: 0; padding: 0; background: transparent; color: var(--foreground); font-size: var(--text-xs); text-align: right; }
  .table td::before { content: attr(data-label); flex: none; color: var(--text-muted); text-align: left; }
  .table[data-selectable] td[data-primary]:not([data-sortable]) { padding-left: 0; }
  .table td[data-primary] { grid-column: 1; grid-row: 1; display: block; margin-bottom: 4px; font-size: var(--text-sm); font-weight: 500; text-align: left; }
  .table td[data-lead] { grid-column: 2; grid-row: 1; display: block; margin-bottom: 4px; font-size: var(--text-sm); font-weight: 500; }
  .table td[data-primary]::before, .table td[data-lead]::before, .table td.selectCell::before, .table td.empty::before { content: none; }
  /* Sıralanan değer, geniş ekrandaki renkli sütunun yankısı olarak koyulaşır. */
  .table td[data-sorted]:not([data-primary]):not([data-lead]) { font-weight: 500; }
  /* Onay kutusu kartın sol üstünde, başlık satırı hizasında. Izgara satırı verilmez; yoksa mutlak konum o satırın alanına bağlanır. */
  .table td.selectCell { position: absolute; grid-column: auto; grid-row: auto; top: 0; left: var(--space-1); display: flex; width: 36px; height: 46px; align-items: center; padding: 0; }
  .table td.selectCell .selectHit { justify-content: center; }
  .table tbody tr:has(.empty) { display: block; padding: var(--space-6) var(--space-4); }
  .table .empty { display: block; height: auto !important; padding: 0; }
  .table[data-selectable] tbody tr:has(.empty) { padding-left: var(--space-4); }
}
@media (max-width: 620px) and (hover: hover) and (pointer: fine) {
  .table tbody tr:hover { --row-fill: color-mix(in oklab, var(--foreground) 3%, var(--surface)); }
  .table[data-selectable] tbody tr[data-selected]:hover { --row-fill: color-mix(in oklab, var(--accent) 11%, var(--surface)); }
  .table tbody tr:hover td { background: transparent; }
}

@media (prefers-reduced-motion: reduce) {
  .table th, .table td, .table tbody tr, .sortInner, .sortHint, .selectBox, .count, .clear, .table th .sortButton { transition: none !important; }
  .selectInput:active + .selectBox { transform: none; }
}

@keyframes stripFade { to { opacity: 1; } }

"use client";

import { useLayoutEffect, useMemo, useRef, useState } from "react";
import type { KeyboardEvent, MouseEvent as ReactMouseEvent, ReactNode, RefObject } from "react";
import { ArrowUp } from "lucide-react";
import { AnimatePresence, animate, motion, useMotionValue, useReducedMotion, type Transition, type Variants } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import { Pagination } from "../pagination/pagination";
import { compareText, formatCell, pageCountOf, pageSpan, rangeLabel, sortAnnouncement, type CellCurrency, type CellFormat } from "./sortable-data-table-format";
import styles from "./sortable-data-table.module.css";

export type SortDirection = "asc" | "desc";
export type SortState = { key: string; direction: SortDirection };
export type { CellCurrency, CellFormat };

export type DataColumn<T> = {
  key: string;
  label: string;
  sortable?: boolean;
  render?: (value: unknown, row: T) => ReactNode;
  /** Sütunu sağa yaslar, eş genişlikli rakam kullanır. Her değer sayıysa kendiliğinden anlaşılır. */
  numeric?: boolean;
  /** Yazım (ABACUS): "money" kuruş tam sayısını "₺1.234,50" yazar ve sağa yaslar; "number" "1.234,5"; "date" "16.10.2026"; "text" olduğu gibi. Verilmezse türe bakılır. */
  format?: CellFormat;
  /** "money" sütununun birimi. Varsayılan TRY. */
  currency?: CellCurrency;
  /** "number" sütununun sabit ondalık basamağı. */
  digits?: number;
  /** Sabit genişlik, 120 ya da "20%". Diğer sütunlar bir kez ölçülüp tutulur; sıralama onları yeniden dizmez. */
  width?: number | string;
};

export type SortableDataTableProps<T extends Record<string, unknown>> = {
  rows: T[];
  columns: DataColumn<T>[];
  rowKey: keyof T | ((row: T) => string);
  caption?: string;
  emptyMessage?: string;
  /** İlk çizimde uygulanan sıralama. */
  defaultSort?: SortState;
  onSortChange?: (sort: SortState) => void;
  /** Onay kutusu sütunu, satıra tıklayarak seçim ve temizleme düğmeli sayı satırı ekler. */
  selectable?: boolean;
  selectedKeys?: string[];
  defaultSelectedKeys?: string[];
  onSelectionChange?: (keys: string[]) => void;
  /** Sayı satırındaki ad, "6 proje" gibi. Türkçede sayıdan sonra tekil kalır; iki biçim Arc ile uyum için durur. */
  itemName?: { one: string; other: string };
  /** Sayfa boyu. Verilirse tablo sayfalanır ve altta sayfalama çıkar (katalogdaki `pagination`). */
  pageSize?: number;
  /** Denetimli sayfa (1'den başlar). Verilmezse tablo kendi tutar; sıralama değişince 1. sayfaya döner. */
  page?: number;
  defaultPage?: number;
  onPageChange?: (page: number) => void;
};

const isEmpty = (value: unknown) => value == null || value === "";
const comparable = (value: unknown) => value instanceof Date ? value.getTime() : value;
const blur = (px: number) => `blur(${px}px)`;
const enter: Transition = { duration: motionTokens.duration.standard, ease: [...motionTokens.ease.enter] };
const leave: Transition = { duration: motionTokens.duration.fast, ease: [...motionTokens.ease.standard] };
const instant: Transition = { duration: motionTokens.duration.instant };
/** Değişen metin gittiği yandan yükselir, öbür yandan kalkar. */
const rise: Variants = {
  enter: (direction: number) => ({ opacity: 0, y: `${.3 * direction}em`, filter: blur(motionTokens.blur.soft) }),
  shown: { opacity: 1, y: "0em", filter: blur(0), transition: enter },
  gone: (direction: number) => ({ opacity: 0, y: `${-.3 * direction}em`, filter: blur(motionTokens.blur.subtle), transition: leave }),
};
/** Azaltılmış hareket rise ile aynı özellikleri tutar (kayma ve bulanıklık yok); sunucu ve istemci aynı stili çizer. */
const fade: Variants = { enter: { opacity: 0, y: "0em", filter: blur(0) }, shown: { opacity: 1, y: "0em", filter: blur(0), transition: instant }, gone: { opacity: 0, y: "0em", filter: blur(0), transition: instant } };
/** Tik ve tire aynı üç noktayı paylaşır; başlık kutusu "hepsi" ile "bazısı" arasında biçim değiştirir. */
const checkPath = "M4.25 9.25 L7.25 12.25 L13.75 5.75";
const dashPath = "M4.75 9 L9 9 L13.25 9";

/** Yerinde değişen metin. Yuva yeni genişliğe kayar; yanındaki sözcükler zıplamaz. */
function Swap({ value, direction, reduced, className }: { value: string; direction: number; reduced: boolean; className?: string }) {
  const inner = useRef<HTMLSpanElement>(null);
  const width = useMotionValue<number | string>("auto");
  useLayoutEffect(() => {
    const node = inner.current;
    if (!node) return;
    let settled = false;
    const measure = () => {
      const next = node.getBoundingClientRect().width;
      if (settled && !reduced) animate(width, next, motionTokens.spring.morph); else width.jump(next);
      settled = true;
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(node);
    return () => observer.disconnect();
  }, [reduced, width]);
  return <motion.span className={[styles.swap, className].filter(Boolean).join(" ")} style={{ width }}>
    <span ref={inner} className={styles.swapInner}>
      <AnimatePresence mode="popLayout" initial={false} custom={direction}>
        <motion.span key={value} className={styles.swapText} custom={direction} variants={reduced ? fade : rise} initial="enter" animate="shown" exit="gone">{value}</motion.span>
      </AnimatePresence>
    </span>
  </motion.span>;
}

/** Ok, sütun sıralanınca belirir ve yön değişince yayla döner. */
function SortGlyph({ active, descending, reduced }: { active: boolean; descending: boolean; reduced: boolean }) {
  const rotate = useMotionValue(descending ? 180 : 0);
  const seen = useRef({ active, hiddenAt: -Infinity });
  useLayoutEffect(() => {
    const state = seen.current;
    if (active) {
      // Yalnız ok görünürken döner; yeni beliren ok doğru yönü göstererek başlar.
      const visible = state.active || performance.now() - state.hiddenAt < 160;
      if (visible && !reduced) animate(rotate, descending ? 180 : 0, motionTokens.spring.snappy);
      else rotate.jump(descending ? 180 : 0);
    } else if (state.active) state.hiddenAt = performance.now();
    state.active = active;
  }, [active, descending, reduced, rotate]);
  const transition: Transition = reduced ? instant : active ? { opacity: enter, filter: enter, scale: motionTokens.spring.snappy } : { duration: motionTokens.duration.instant, ease: [...motionTokens.ease.standard] };
  return <span className={styles.sortIcon} aria-hidden="true">
    <ArrowUp className={styles.sortHint} size={16} strokeWidth={1.75} />
    <motion.span className={styles.sortArrow} style={{ rotate }} initial={false} animate={active ? { opacity: 1, scale: 1, filter: blur(0) } : { opacity: 0, scale: .6, filter: blur(motionTokens.blur.subtle) }} transition={transition}><ArrowUp size={16} strokeWidth={1.75} /></motion.span>
  </span>;
}

function SelectBox({ checked, mixed = false, label, nav, reduced, onToggle, inputRef }: { checked: boolean; mixed?: boolean; label: string; nav: "head" | "row"; reduced: boolean; onToggle: (extend: boolean) => void; inputRef?: RefObject<HTMLInputElement | null> }) {
  const local = useRef<HTMLInputElement>(null);
  const ref = inputRef ?? local;
  const on = checked || mixed;
  useLayoutEffect(() => { if (ref.current) ref.current.indeterminate = mixed; }, [mixed, ref]);
  const opacity: Transition = { duration: on ? motionTokens.duration.instant : motionTokens.duration.fast, ease: [...motionTokens.ease.standard] };
  return <label className={styles.selectHit}>
    <input ref={ref} type="checkbox" className={styles.selectInput} checked={checked} aria-label={label} data-nav={nav} onChange={event => onToggle((event.nativeEvent as MouseEvent).shiftKey === true)} />
    <span className={styles.selectBox} data-on={on || undefined} aria-hidden="true">
      <motion.span className={styles.selectFill} initial={false} animate={{ opacity: on ? 1 : 0, scale: on ? 1 : .6 }} transition={reduced ? { duration: 0 } : { scale: motionTokens.spring.snappy, opacity }} />
      <svg className={styles.selectMark} viewBox="0 0 18 18" fill="none" focusable="false">
        <motion.path initial={false} animate={{ d: mixed ? dashPath : checkPath, pathLength: on ? 1 : 0, opacity: on ? 1 : 0 }} transition={reduced ? { duration: 0 } : { d: motionTokens.spring.morph, pathLength: motionTokens.spring.snappy, opacity }} stroke="currentColor" strokeWidth={1.75} strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    </span>
  </label>;
}

export function SortableDataTable<T extends Record<string, unknown>>({ rows, columns, rowKey, caption = "Veri tablosu", emptyMessage = "Gösterilecek kayıt yok", defaultSort, onSortChange, selectable = false, selectedKeys, defaultSelectedKeys, onSelectionChange, itemName = { one: "kayıt", other: "kayıt" }, pageSize, page: pageProp, defaultPage = 1, onPageChange }: SortableDataTableProps<T>) {
  const reduced = useReducedMotion() ?? false;
  const tableRef = useRef<HTMLTableElement>(null);
  const selectAllRef = useRef<HTMLInputElement>(null);
  const anchor = useRef<string | null>(null);
  const [sort, setSort] = useState<SortState | null>(defaultSort ?? null);
  const [announcement, setAnnouncement] = useState("");
  const [internalSelection, setInternalSelection] = useState<string[]>(defaultSelectedKeys ?? []);
  const selection = useMemo(() => new Set(selectedKeys ?? internalSelection), [internalSelection, selectedKeys]);
  const [internalPage, setInternalPage] = useState(defaultPage);

  const sortedRows = useMemo(() => {
    if (!sort) return rows;
    return rows.map((row, index) => ({ row, index })).sort((a, b) => {
      const left = comparable(a.row[sort.key]);
      const right = comparable(b.row[sort.key]);
      // Boş değerler iki yönde de en altta kalır.
      if (isEmpty(left) || isEmpty(right)) return isEmpty(left) === isEmpty(right) ? a.index - b.index : isEmpty(left) ? 1 : -1;
      const result = typeof left === "number" && typeof right === "number" ? left - right : compareText(String(left), String(right));
      return (sort.direction === "asc" ? result : -result) || a.index - b.index;
    }).map(entry => entry.row);
  }, [rows, sort]);

  const numeric = useMemo(() => new Set(columns.filter(column => column.numeric ?? (column.format === "money" || (column.format !== "date" && column.format !== "text" && rows.some(row => typeof row[column.key] === "number") && rows.every(row => typeof row[column.key] === "number" || isEmpty(row[column.key]))))).map(column => column.key)), [columns, rows]);
  // Dar ekran kartında başlık satırının sağına çıkan sayı: ilk sütun dışındaki ilk sayı sütunu.
  const leadKey = columns.find((column, index) => index > 0 && numeric.has(column.key))?.key;
  const getRowKey = (row: T) => String(typeof rowKey === "function" ? rowKey(row) : row[rowKey]);
  const allKeys = sortedRows.map(getRowKey);

  // Sayfalama (SNN ekledi): seçim bütün satırlarda tutulur; "hepsini seç", ok tuşları ve Shift aralığı görünen sayfada çalışır.
  const pageCount = pageCountOf(allKeys.length, pageSize);
  const paged = Boolean(pageSize) && pageCount > 1;
  const page = Math.min(Math.max(1, pageProp ?? internalPage), pageCount);
  const pageRows = pageSize ? sortedRows.slice((page - 1) * pageSize, page * pageSize) : sortedRows;
  const keys = pageSize ? allKeys.slice((page - 1) * pageSize, page * pageSize) : allKeys;
  const order = keys.join("\u0000");
  const selectedCount = allKeys.filter(key => selection.has(key)).length;
  const pageSelected = keys.filter(key => selection.has(key)).length;
  const allSelected = keys.length > 0 && pageSelected === keys.length;
  function goToPage(next: number) {
    if (pageProp === undefined) setInternalPage(next);
    onPageChange?.(next);
  }

  // Doğal sütun genişlikleri bir kez ölçülür, sonra sabit düzenle tutulur; satırlar yer değiştirirken hiçbir şey yeniden dizilmez.
  const signature = [selectable ? "select" : "", ...columns.map(column => column.key)].join("\u0000");
  const [locked, setLocked] = useState<{ signature: string; widths: Record<string, number> } | null>(null);
  const widths = locked?.signature === signature ? locked.widths : null;
  useLayoutEffect(() => {
    const table = tableRef.current;
    if (!table || widths) return;
    const measure = () => {
      const total = table.getBoundingClientRect().width;
      if (!total || getComputedStyle(table).display !== "table") return false;
      const next: Record<string, number> = {};
      table.querySelectorAll<HTMLElement>("thead th[data-key]").forEach(cell => { next[cell.dataset.key ?? ""] = cell.getBoundingClientRect().width / total * 100; });
      setLocked({ signature, widths: next });
      return true;
    };
    if (measure()) return;
    const observer = new ResizeObserver(() => { if (measure()) observer.disconnect(); });
    observer.observe(table);
    return () => observer.disconnect();
  }, [signature, widths]);

  // Sıralanan sütunun altındaki sabit renk bandı, satırlar birbirini geçerken açılan boşlukları doldurur.
  const [band, setBand] = useState<{ left: number; width: number } | null>(null);
  const seenSort = useRef(false);
  useLayoutEffect(() => {
    const table = tableRef.current;
    const key = sort?.key;
    const update = () => {
      const cell = key ? table?.querySelector<HTMLElement>(`thead th[data-key="${CSS.escape(key)}"]`) : null;
      setBand(current => !cell ? null : current?.left === cell.offsetLeft && current.width === cell.offsetWidth ? current : { left: cell.offsetLeft, width: cell.offsetWidth });
    };
    update();
    if (!table || !key) return;
    // Telefonda başlık kayan bir sıralama düğmeleri şerididir; etkin olan görünür tutulur.
    const cell = table.querySelector<HTMLElement>(`thead th[data-key="${CSS.escape(key)}"]`);
    const strip = cell?.parentElement;
    if (cell && strip && strip.scrollWidth > strip.clientWidth && getComputedStyle(table).display !== "table") {
      const bounds = strip.getBoundingClientRect(), target = cell.getBoundingClientRect(), inset = 8;
      const start = Math.max(bounds.left, strip.querySelector("th:not([data-key])")?.getBoundingClientRect().right ?? bounds.left) + inset;
      const shift = target.right > bounds.right - inset ? target.right - bounds.right + inset : target.left < start ? target.left - start : 0;
      if (shift) strip.scrollTo({ left: strip.scrollLeft + shift, behavior: reduced || !seenSort.current ? "auto" : "smooth" });
    }
    seenSort.current = true;
    const observer = new ResizeObserver(update);
    observer.observe(table);
    return () => observer.disconnect();
  }, [reduced, sort?.key, widths]);

  const shownCount = selectedCount || allKeys.length;
  const noun = selectedCount ? "seçili" : allKeys.length === 1 ? itemName.one : itemName.other;
  const [lastCount, setLastCount] = useState(shownCount);
  const [countDirection, setCountDirection] = useState(1);
  if (shownCount !== lastCount) { setLastCount(shownCount); setCountDirection(shownCount > lastCount ? 1 : -1); }

  function sortBy(column: DataColumn<T>) {
    const next: SortState = { key: column.key, direction: sort?.key === column.key && sort.direction === "asc" ? "desc" : "asc" };
    setSort(next);
    onSortChange?.(next);
    if (pageSize && page !== 1) goToPage(1);
    setAnnouncement(sortAnnouncement(column.label, next.direction));
  }

  function commit(next: Set<string>) {
    const list = allKeys.filter(key => next.has(key));
    if (selectedKeys === undefined) setInternalSelection(list);
    onSelectionChange?.(list);
    setAnnouncement(list.length ? `${list.length} / ${allKeys.length} seçildi` : "Seçim temizlendi");
  }

  function toggleRow(key: string, extend: boolean) {
    const next = new Set(selection);
    const checked = !selection.has(key);
    const from = extend && anchor.current ? keys.indexOf(anchor.current) : -1;
    const to = keys.indexOf(key);
    (from < 0 ? [key] : keys.slice(Math.min(from, to), Math.max(from, to) + 1)).forEach(item => checked ? next.add(item) : next.delete(item));
    anchor.current = key;
    commit(next);
  }

  function togglePage() {
    const next = new Set(selection);
    keys.forEach(key => allSelected ? next.delete(key) : next.add(key));
    commit(next);
  }

  function clearSelection() {
    commit(new Set());
    selectAllRef.current?.focus();
  }

  function onRowClick(event: ReactMouseEvent<HTMLTableRowElement>, key: string) {
    if (!selectable || (event.target as HTMLElement).closest("a, button, input, label, select, textarea, [role='button'], [contenteditable='true']") || window.getSelection()?.toString()) return;
    toggleRow(key, event.shiftKey);
    // Klavye yolu işaretçinin bıraktığı yerden sürer; oklar bu satırdan devam eder.
    event.currentTarget.querySelector<HTMLInputElement>("input[type='checkbox']")?.focus({ preventScroll: true });
  }

  /** Oklar başlık denetimlerinde ve satır kutularında gezer; Escape seçimi temizler. */
  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    const target = event.target as HTMLElement;
    if (event.key === "Escape" && selectedCount) {
      event.preventDefault();
      event.stopPropagation();
      if (target.dataset.clear !== undefined) clearSelection(); else commit(new Set());
      return;
    }
    const nav = target.dataset.nav;
    if (!nav) return;
    const list = (name: string) => [...event.currentTarget.querySelectorAll<HTMLElement>(`[data-nav="${name}"]`)];
    const items = list(nav);
    const index = items.indexOf(target);
    const steps: Record<string, [HTMLElement[], number]> = nav === "head"
      ? { ArrowRight: [items, index + 1], ArrowLeft: [items, index - 1], Home: [items, 0], End: [items, items.length - 1], ...(target === selectAllRef.current ? { ArrowDown: [list("row"), 0] } : {}) }
      : { ArrowDown: [items, index + 1], ArrowUp: index === 0 && selectAllRef.current ? [[selectAllRef.current], 0] : [items, index - 1], Home: [items, 0], End: [items, items.length - 1] };
    const step = steps[event.key];
    const next = step?.[0][step[1]];
    if (!next) return;
    event.preventDefault();
    next.focus();
  }

  return <div className={styles.wrapper} onKeyDown={onKeyDown}>
    <div className={styles.scroller}>
      {band ? <span className={styles.band} style={{ left: band.left, width: band.width }} aria-hidden="true" /> : null}
      <table ref={tableRef} role="table" className={styles.table} data-fixed={widths ? "" : undefined} data-selectable={selectable || undefined}>
        <caption>{caption}</caption>
        <colgroup>
          {selectable ? <col className={styles.selectCol} /> : null}
          {columns.map((column, index) => <col key={column.key} style={{ width: column.width !== undefined ? (typeof column.width === "number" ? `${column.width}px` : column.width) : widths && index > 0 ? `${widths[column.key]}%` : undefined }} />)}
        </colgroup>
        <thead role="rowgroup"><tr role="row">
          {selectable ? <th scope="col" role="columnheader" className={styles.selectCell}><SelectBox inputRef={selectAllRef} checked={allSelected} mixed={pageSelected > 0 && !allSelected} label={pageSize ? "Bu sayfadaki tüm satırları seç" : "Tüm satırları seç"} nav="head" reduced={reduced} onToggle={togglePage} /></th> : null}
          {columns.map((column, index) => {
            const active = sort?.key === column.key;
            const sortable = column.sortable !== false;
            return <th key={column.key} scope="col" role="columnheader" data-key={column.key} data-primary={index === 0 || undefined} data-sorted={active || undefined} data-numeric={numeric.has(column.key) || undefined} data-sortable={sortable || undefined} aria-sort={!sortable ? undefined : active ? (sort.direction === "asc" ? "ascending" : "descending") : "none"}>
              {sortable ? <button className={styles.sortButton} type="button" data-nav="head" onClick={() => sortBy(column)} aria-label={`${column.label} sütununa göre sırala${active ? `, şu an ${sort.direction === "asc" ? "artan" : "azalan"}` : ""}`}>
                <span className={styles.sortInner}><span>{column.label}</span><SortGlyph active={active} descending={active && sort.direction === "desc"} reduced={reduced} /></span>
              </button> : column.label}
            </th>;
          })}
        </tr></thead>
        <tbody role="rowgroup">{pageRows.length ? pageRows.map((row, index) => {
          const key = keys[index]!;
          const selected = selectable && selection.has(key);
          return <motion.tr key={key} role="row" layout={reduced ? false : "position"} layoutDependency={order} transition={motionTokens.spring.smooth} data-selected={selected || undefined} onClick={event => onRowClick(event, key)} onMouseDown={event => { if (selectable && event.shiftKey) event.preventDefault(); }}>
            {selectable ? <td role="cell" className={styles.selectCell}><SelectBox checked={selected} label={`${String(row[columns[0]?.key as string] ?? key)} seç`} nav="row" reduced={reduced} onToggle={extend => toggleRow(key, extend)} /></td> : null}
            {columns.map((column, columnIndex) => <td key={column.key} role="cell" data-label={column.label} data-primary={columnIndex === 0 || undefined} data-lead={column.key === leadKey || undefined} data-sorted={sort?.key === column.key || undefined} data-numeric={numeric.has(column.key) || undefined}>{column.render ? column.render(row[column.key], row) : formatCell(row[column.key], column)}</td>)}
          </motion.tr>;
        }) : <tr role="row"><td role="cell" className={styles.empty} colSpan={columns.length + (selectable ? 1 : 0)}>{emptyMessage}</td></tr>}</tbody>
      </table>
    </div>
    {selectable || paged ? <div className={styles.footer} data-paged={paged || undefined}>
      {selectable ? <span className={styles.selection}>
        <span className={styles.srOnly}>{shownCount} {noun}</span>
        <span className={styles.count} data-active={selectedCount > 0 || undefined} aria-hidden="true">
          <Swap className={styles.number} value={String(shownCount)} direction={countDirection} reduced={reduced} />
          <Swap value={noun} direction={selectedCount ? 1 : -1} reduced={reduced} />
        </span>
        <AnimatePresence initial={false}>{selectedCount ? <motion.button key="clear" type="button" className={styles.clear} data-clear="" onClick={clearSelection} initial={reduced ? { opacity: 0 } : { opacity: 0, scale: .96, filter: blur(motionTokens.blur.soft) }} animate={{ opacity: 1, scale: 1, filter: blur(0) }} exit={reduced ? { opacity: 0, transition: instant } : { opacity: 0, scale: .98, filter: blur(motionTokens.blur.subtle), transition: leave }} transition={reduced ? instant : enter} whileTap={reduced ? undefined : { scale: .97, transition: { duration: motionTokens.duration.instant } }}>Seçimi temizle</motion.button> : null}</AnimatePresence>
      </span> : null}
      {/* Sayfalama (SNN ekledi): seçim satırıyla aynı satırda; dar alanda alta iner. */}
      {paged ? <span className={styles.pager}>
        <span className={styles.range}>{selectable ? pageSpan(page, pageSize ?? 0, allKeys.length) : rangeLabel(page, pageSize ?? 0, allKeys.length, itemName.other)}</span>
        <Pagination page={page} pageCount={pageCount} onPageChange={goToPage} label={`${caption} sayfaları`} />
      </span> : null}
    </div> : null}
    <p className={styles.srOnly} role="status">{announcement}</p>
  </div>;
}

export default SortableDataTable;
